const REPORTS = [
  { key: 'grade_changes', name: 'Grade changes', action_count: 6 },
  { key: 'student_records', name: 'Student record changes', action_count: 6 },
  { key: 'registration_overrides', name: 'Registration overrides', action_count: 6 },
  { key: 'system_activity', name: 'System activity', action_count: 12 },
];

const REPORT_MODULES: Record<string, string[]> = {
  grade_changes: ['Grades'],
  student_records: ['Students'],
  registration_overrides: ['Registration', 'Courses'],
  system_activity: ['Users and access', 'System settings', 'Academic calendar'],
};

/**
 * Dean and Auditor only — mirrors `require_role(PRINCIPAL, AUDITOR)` on the server.
 *
 * ⚠️ `sysadmin` WAS IN THIS LIST and is not any more (Sep 2026). The server never
 * allowed them on `/audit`: D45 Phase 7's central `technical_role_scope` guard refused
 * the role and the route was corrected, because this trail is mostly academic records
 * and §48 keeps that role out of exactly those. The demo was allowing them, which is
 * how a demo certifies behaviour the backend does not have — for the fourth recorded
 * time in this project. The Registrar is absent for the reason the server gives: they
 * are the log's most frequent subject.
 */
function assertReader(cookies: Record<string, string>) {
  const role = cookies['sis_mock_session'] ?? 'principal';
  if (!['principal', 'auditor'].includes(role)) {
    return errorResponse(403, 'forbidden', 'You do not have access to this resource.');
  }
  return null;
}

export const auditHandlers = [
  http.get(`${API_BASE_URL}/audit`, ({ request, cookies }) => {
    const denied = assertReader(cookies);
    if (denied) return denied;

    const url = new URL(request.url);
    const report = url.searchParams.get('report');
    const module = url.searchParams.get('module');
    const search = (url.searchParams.get('search') ?? '').toLowerCase();

    let items = ENTRIES;
    if (report) {
      const allowed = REPORT_MODULES[report] ?? [];
      items = items.filter((e) => allowed.includes(e.module));
    }
    if (module) items = items.filter((e) => e.module === module);
    if (search) {
      items = items.filter((e) =>
        `${e.description} ${e.subject ?? ''} ${e.reason ?? ''}`.toLowerCase().includes(search),
      );
    }

    return HttpResponse.json({
      items,
      total: items.length,
      page: 1,
      page_size: 25,
      // The demo set is entirely post-Phase-7, so the "before/after unavailable" notice
      // stays off. Flipping this to true is the way to see that state.
      includes_pre_phase7_rows: false,
    });
  }),

  http.get(`${API_BASE_URL}/audit/filters`, ({ cookies }) => {
    const denied = assertReader(cookies);
    if (denied) return denied;
    return HttpResponse.json({
      modules: [...new Set(ENTRIES.map((e) => e.module))],
      actions: REPORTS.map((r) => r.key),
      actors: [
        { id: 'mock-dean', name: 'Alicia Mendez', role: 'Dean' },
        { id: 'mock-lecturer', name: 'Alicia Cano', role: 'Lecturer' },
        { id: 'mock-registrar', name: 'Rosa Chan', role: 'Registrar' },
      ],
    });
  }),

  http.get(`${API_BASE_URL}/audit/reports`, ({ cookies }) => {
    const denied = assertReader(cookies);
    if (denied) return denied;
    return HttpResponse.json(REPORTS);
  }),
];
